const articleTitle=(k,a)=>{const base=['es','en','fr','de','pt'];return base.includes(k)?a[base.indexOf(k)+1]:extraArticleTitles[k][articles.indexOf(a)]};
for(const [key,titles] of Object.entries(extraArticleTitles)){if(titles.length!==articles.length)throw new Error(`${key}: expected ${articles.length} article titles, got ${titles.length}`)}

const generic={
es:{why:'Qué debes saber',plan:'Cómo planearlo bien',day:'El día de la actividad',avoid:'Errores que puedes evitar',summary:'Decisión rápida',paras:['La decisión correcta depende de tu nivel, fechas, condición física, experiencia en el agua y del viento real. Comparte esos datos antes de reservar para recibir una recomendación útil.','En Cartagena las condiciones cambian por hora y por zona. Mantén flexible el momento de la sesión y confirma por WhatsApp antes de desplazarte.','Revisa equipo, zona de lanzamiento, bañistas, obstáculos y procedimiento de seguridad. Si las condiciones no corresponden a tu nivel, se adapta el ejercicio o se reprograma.','No compres vuelos, equipaje deportivo o servicios no reembolsables basándote solamente en una media mensual. Contrasta la planificación con fuentes oficiales y la revisión local.']},
en:{why:'What you need to know',plan:'How to plan it well',day:'On the activity day',avoid:'Mistakes you can avoid',summary:'Quick decision',paras:['The right decision depends on your level, dates, fitness, water experience and the actual wind. Share those details before booking to receive a useful recommendation.','Conditions in Cartagena change by hour and area. Keep the session window flexible and reconfirm by WhatsApp before travelling to the beach.','Check equipment, launch area, swimmers, obstacles and the safety procedure. If conditions do not match your level, the exercise changes or the session is rescheduled.','Do not buy non-refundable flights, sports baggage or services based only on a monthly average. Compare your plan with official sources and a local beach assessment.']},
fr:{why:'Ce qu’il faut savoir',plan:'Bien organiser la session',day:'Le jour de l’activité',avoid:'Erreurs à éviter',summary:'Décision rapide',paras:['La bonne décision dépend du niveau, des dates, de la condition physique, de l’expérience dans l’eau et du vent réel. Communiquez ces éléments avant de réserver.','À Cartagena, les conditions varient selon l’heure et la zone. Gardez une plage horaire flexible et reconfirmez par WhatsApp avant le déplacement.','Vérifiez matériel, zone de décollage, baigneurs, obstacles et procédure de sécurité. Si les conditions ne conviennent pas, l’exercice change ou la session est reportée.','N’achetez pas de vol, bagage sportif ou service non remboursable sur la seule base d’une moyenne mensuelle. Consultez les sources officielles et l’évaluation locale.']},
de:{why:'Was du wissen solltest',plan:'So planst du richtig',day:'Am Tag der Aktivität',avoid:'Vermeidbare Fehler',summary:'Schnelle Entscheidung',paras:['Die richtige Entscheidung hängt von Level, Reisedaten, Fitness, Wassererfahrung und tatsächlichem Wind ab. Teile diese Angaben vor der Buchung.','In Cartagena ändern sich Bedingungen je nach Uhrzeit und Bereich. Halte das Zeitfenster flexibel und bestätige per WhatsApp vor der Fahrt zum Strand.','Prüfe Material, Startzone, Badegäste, Hindernisse und Sicherheitsablauf. Passen Bedingungen nicht zum Level, wird die Übung geändert oder verschoben.','Buche keine nicht erstattbaren Flüge, Sportgepäck oder Leistungen nur aufgrund eines Monatsmittels. Nutze offizielle Quellen und die lokale Beurteilung.']},
pt:{why:'O que você precisa saber',plan:'Como planejar bem',day:'No dia da atividade',avoid:'Erros que você pode evitar',summary:'Decisão rápida',paras:['A decisão correta depende do nível, datas, condição física, experiência na água e do vento real. Envie essas informações antes de reservar.','Em Cartagena as condições mudam conforme o horário e a área. Mantenha a janela da sessão flexível e confirme pelo WhatsApp antes de ir à praia.','Revise equipamento, área de lançamento, banhistas, obstáculos e procedimento de segurança. Se as condições não combinarem com seu nível, o exercício muda ou a sessão é remarcada.','Não compre voos, bagagem esportiva ou serviços não reembolsáveis usando apenas uma média mensal. Compare com fontes oficiais e avaliação local.']},
it:{why:'Cosa devi sapere',plan:'Come pianificare bene',day:'Il giorno dell’attività',avoid:'Errori da evitare',summary:'Decisione rapida',paras:['La scelta giusta dipende da livello, date, forma fisica, esperienza in acqua e vento reale. Comunica questi dati prima di prenotare per ricevere un consiglio utile.','A Cartagena le condizioni cambiano in base all’ora e alla zona. Mantieni flessibile l’orario e riconferma su WhatsApp prima di andare in spiaggia.','Controlla attrezzatura, area di lancio, bagnanti, ostacoli e procedura di sicurezza. Se le condizioni non sono adatte al tuo livello, l’esercizio cambia o la sessione viene riprogrammata.','Non acquistare voli, bagaglio sportivo o servizi non rimborsabili basandoti solo su una media mensile. Confronta il piano con fonti ufficiali e valutazione locale.']},
ru:{why:'Что нужно знать',plan:'Как правильно спланировать',day:'В день занятия',avoid:'Ошибки, которых можно избежать',summary:'Короткое решение',paras:['Правильное решение зависит от вашего уровня, дат, физической формы, опыта на воде и фактического ветра. Сообщите эти данные до бронирования.','В Картахене условия меняются в зависимости от времени и участка. Оставьте окно сессии гибким и подтвердите его в WhatsApp перед поездкой на пляж.','Проверьте снаряжение, зону запуска, купающихся, препятствия и процедуру безопасности. Если условия не соответствуют уровню, упражнение меняют или сессию переносят.','Не покупайте невозвратные билеты, спортивный багаж или услуги, опираясь только на среднемесячные данные. Сверяйтесь с официальными источниками и местной оценкой.']},
zh:{why:'你需要了解什么',plan:'如何正确规划',day:'活动当天',avoid:'可以避免的错误',summary:'快速判断',paras:['正确选择取决于你的水平、日期、体能、水上经验和实际风况。预订前请提供这些信息，以便获得有用建议。','卡塔赫纳的条件会随时间和区域变化。请保持课程时间灵活，并在前往海滩前通过 WhatsApp 再次确认。','检查装备、起飞区、游泳者、障碍物和安全程序。如果条件不适合你的水平，应调整练习或改期。','不要只根据月度平均值购买不可退款的机票、运动行李或服务。请结合官方来源和当地现场评估。']},
ko:{why:'알아야 할 사항',plan:'잘 계획하는 방법',day:'활동 당일',avoid:'피할 수 있는 실수',summary:'빠른 판단',paras:['올바른 선택은 레벨, 날짜, 체력, 수상 경험, 실제 바람에 따라 달라집니다. 예약 전에 이 정보를 공유해 맞는 안내를 받으세요.','카르타헤나는 시간과 구역에 따라 조건이 달라집니다. 세션 시간을 유연하게 두고 해변으로 가기 전에 WhatsApp으로 다시 확인하세요.','장비, 이륙 구역, 수영객, 장애물, 안전 절차를 확인하세요. 조건이 레벨에 맞지 않으면 연습을 조정하거나 일정을 변경합니다.','월별 평균만 보고 환불 불가 항공권, 스포츠 수하물, 서비스를 구매하지 마세요. 공식 자료와 현지 평가를 함께 확인하세요.']},
ja:{why:'知っておくべきこと',plan:'適切な計画方法',day:'アクティビティ当日',avoid:'避けられる失敗',summary:'簡単な判断',paras:['適切な選択は、レベル、日程、体力、水上経験、実際の風に左右されます。予約前に情報を共有すると、より役立つ提案が受けられます。','カルタヘナのコンディションは時間帯と場所で変わります。セッション時間に余裕を持たせ、ビーチへ向かう前にWhatsAppで再確認してください。','用具、離陸エリア、海水浴客、障害物、安全手順を確認します。条件がレベルに合わない場合は、練習内容を変えるか日程を変更します。','月間平均だけを根拠に返金不可の航空券、スポーツ手荷物、サービスを購入しないでください。公式情報と現地評価を確認しましょう。']}
};

