shell=(l,opts)=>{const k=localeKey(l),u=uiCopy[k],choice=formChoices[k];let html=shellBase(l,opts).replace('>Skip</a>',`>${u.skip}</a>`).replace('aria-label="Menu"',`aria-label="${u.menu}"`).replace('Images generated for visual representation.',u.legal).replace('14 OPTIONS',u.options).replace(`${articles.length} GUIDES`,`${articles.length} ${u.guides}`).replaceAll('DIAGNOSIS · REPAIR · SAFETY',u.repair).replaceAll('Who · How · Why',u.why).replace('<option>Yes / Sí</option><option>No</option>',`<option>${choice[0]}</option><option>${choice[1]}</option>`).replace('bladder &amp; valves',repairLinkLabels[k]).replace(`<a class="floating-wa"`,`<a class="floating-wa" aria-label="${u.wa}"`).replace('>WhatsApp</a>','></a>');for(const [tag,label] of Object.entries(tagTranslations[k]))html=html.replaceAll(`<span class="pill">${tag}</span>`,`<span class="pill">${label}</span>`).replaceAll(`JOURNAL · ${tag.toUpperCase()}`,`JOURNAL · ${label.toUpperCase()}`);for(const [from,to] of sourceReplacements[k]||[])html=html.replaceAll(from,to);return html};

const methodologyBase=methodologyPage;
const methodologyExtra={
 it:['Come ricerchiamo e aggiorniamo le guide','Ogni guida nasce da una domanda concreta del viaggiatore. Distinguiamo clima storico, previsioni, valutazione locale e condizioni commerciali, citando le fonti primarie accanto alle affermazioni pertinenti.','Le immagini sono rappresentazioni generate con IA. Gli strumenti di ricerca possono assistere il testo, ma ogni pagina viene revisionata prima della pubblicazione. Non inventiamo esperienza sul campo, certificazioni o garanzie.','Controlliamo link, date, prezzi e avvisi quando cambiano. Le condizioni del giorno vanno sempre verificate con DIMAR e con una valutazione locale.'],
 ru:['Как мы исследуем и обновляем материалы','Каждый материал начинается с конкретного вопроса путешественника. Мы разделяем исторический климат, прогноз, местную оценку и коммерческие условия и ставим первичные источники рядом с подтверждаемым утверждением.','Изображения являются сгенерированными иллюстрациями. Инструменты могут помогать в исследовании, но каждая страница проходит редакционную проверку. Мы не выдумываем полевой опыт, сертификаты или гарантии.','Мы проверяем ссылки, даты, цены и предупреждения при изменениях. Условия в день занятия необходимо сверять с DIMAR и местной оценкой.'],
 zh:['我们如何研究并更新指南','每篇指南都从旅行者的具体问题出发。我们区分历史气候、天气预报、现场评估和商业条款，并把一手来源放在其支持的陈述旁。','图片为 AI 生成的视觉示意。研究工具可以辅助写作，但每个页面发布前都会经过编辑审查。我们不会虚构实地经验、认证或保证。','链接、日期、价格和提示发生变化时会被复核。当天条件仍须结合 DIMAR 与现场评估确认。'],
 ko:['가이드를 조사하고 업데이트하는 방법','각 가이드는 여행자의 구체적인 질문에서 시작합니다. 과거 기후, 예보, 현지 평가, 상업 조건을 구분하고 관련 주장 옆에 1차 출처를 연결합니다.','이미지는 AI로 생성된 시각 자료입니다. 조사 도구가 글을 도울 수 있지만 모든 페이지는 게시 전에 편집 검토를 거칩니다. 현장 경험, 자격 또는 보장을 꾸며내지 않습니다.','링크, 날짜, 가격, 주의사항이 바뀌면 다시 검토합니다. 당일 조건은 DIMAR 자료와 현지 평가로 확인해야 합니다.'],
 ja:['ガイドの調査と更新方法','各ガイドは旅行者の具体的な疑問から始まります。過去の気候、予報、現地評価、取引条件を区別し、根拠となる一次情報を該当する記述の近くに示します。','画像はAIで生成したイメージです。調査ツールを補助的に使うことはありますが、公開前に編集確認を行います。現場経験、資格、保証を捏造しません。','リンク、日付、価格、注意事項は変更時に見直します。当日の状況はDIMARと現地評価で必ず確認してください。']
};
methodologyPage=(l)=>{const k=localeKey(l);if(!extraLocaleKeys.has(k))return methodologyBase(l);const copy=methodologyExtra[k];const body=hero(copy[0],copy[1],'blog.webp',[l.cta,wa(l.msg)])+`<section class="section"><div class="prose"><h2>${copy[0]}</h2><p>${copy[1]}</p><h2>${uiCopy[k].why}</h2><p>${copy[2]}</p><p>${copy[3]}</p>${sourceSection(k,'wind')}</div></section>`;return shell(l,{title:`${copy[0]} | Kite Cartagena`,desc:copy[1],urlPath:href(l,methodSlugs[k]),body,heroImage:'blog.webp',slugFn:x=>href(x,methodSlugs[localeKey(x)])})};

const faqDataBase=faqData;
const faqExtra={
 it:[['Serve esperienza?','No. Indica che è la tua prima volta per adattare il piano.'],['Il vento è garantito?','No. Confermiamo vicino alla sessione e può essere necessario riprogrammare.'],['Qual è la stagione migliore?','Da dicembre ad aprile è in genere il periodo più costante, senza garanzia giornaliera.'],['Dove si svolge?','La base di riferimento è La Boquilla; l’area esatta dipende dalle condizioni.'],['L’attrezzatura è inclusa?','Dipende dal corso o noleggio e viene confermato per iscritto prima del pagamento.'],['Posso prenotare dall’estero?','Sì. Invia date, livello, peso approssimativo e numero di persone su WhatsApp.'],['Cosa succede se cambia il meteo?','Esercizio, orario o data vengono adattati secondo sicurezza e disponibilità.'],['Chi commercializza l’attività?','Dunas & Olas, operatore turistico che pubblica il RNT 292710.']],
 ru:[['Нужен ли опыт?','Нет. Сообщите, что это ваш первый раз, чтобы адаптировать план.'],['Ветер гарантирован?','Нет. Мы подтверждаем условия ближе к занятию и при необходимости переносим его.'],['Когда лучший сезон?','С декабря по апрель условия обычно стабильнее, но ежедневной гарантии нет.'],['Где проходит занятие?','Основная точка — Ла-Бокилья; точная зона зависит от условий.'],['Снаряжение включено?','Это зависит от курса или аренды и подтверждается письменно до оплаты.'],['Можно забронировать из другой страны?','Да. Отправьте даты, уровень, примерный вес и число участников в WhatsApp.'],['Что происходит при изменении погоды?','Упражнение, время или дата меняются с учетом безопасности и доступности.'],['Кто продает услугу?','Dunas & Olas — туристический оператор с опубликованным RNT 292710.']],
 zh:[['需要经验吗？','不需要。请说明这是第一次，以便调整课程计划。'],['风力有保证吗？','没有。我们会在临近课程时确认，必要时会改期。'],['最佳季节是什么时候？','12 月至 4 月通常更稳定，但不保证每天都有合适条件。'],['课程在哪里进行？','参考基地位于拉博基亚；具体区域根据当天条件确认。'],['包含装备吗？','取决于所选课程或租赁方案，付款前会书面确认。'],['可以从国外预订吗？','可以。请通过 WhatsApp 发送日期、水平、约重和人数。'],['天气变化怎么办？','会根据安全和可用性调整练习、时间或日期。'],['由谁提供商业服务？','Dunas & Olas，公布 RNT 292710 的旅游服务商。']],
 ko:[['경험이 필요한가요?','아니요. 처음이라면 알려주시면 계획을 조정합니다.'],['바람이 보장되나요?','아니요. 세션에 가까운 시점에 확인하며 필요하면 일정을 변경합니다.'],['가장 좋은 시즌은 언제인가요?','12월부터 4월이 대체로 가장 안정적이지만 매일 보장되지는 않습니다.'],['어디에서 진행되나요?','기준 장소는 라보키야이며 정확한 구역은 당일 조건에 따라 결정됩니다.'],['장비가 포함되나요?','선택한 강습 또는 대여에 따라 다르며 결제 전에 서면으로 확인합니다.'],['해외에서도 예약할 수 있나요?','네. 날짜, 수준, 대략적인 체중과 인원을 WhatsApp으로 보내주세요.'],['날씨가 바뀌면 어떻게 하나요?','안전과 가능 여부에 따라 연습, 시간 또는 날짜를 조정합니다.'],['누가 서비스를 판매하나요?','RNT 292710을 공개한 관광사업자 Dunas & Olas입니다.']],
 ja:[['経験は必要ですか？','いいえ。初めてであることを伝えていただければプランを調整します。'],['風は保証されますか？','いいえ。セッション直前に確認し、必要に応じて日程を変更します。'],['ベストシーズンはいつですか？','12月から4月は比較的安定しますが、毎日の保証はありません。'],['どこで行いますか？','基点はラ・ボキージャです。正確なエリアは当日の状況で決めます。'],['用具は含まれますか？','選択したレッスンやレンタルにより異なり、支払い前に書面で確認します。'],['海外から予約できますか？','はい。日程、レベル、おおよその体重、人数をWhatsAppで送ってください。'],['天候が変わった場合は？','安全性と空き状況に応じて内容、時間、日付を調整します。'],['誰が販売していますか？','RNT 292710を公開する観光事業者Dunas & Olasです。']]
};
