windTable=(k,l)=>{if(!extraLocaleKeys.has(k))return windTableBase(k,l);const months=monthExtra[k],words=windWords[k],levels=[5,5,5,4,3,3,2,2,2,3,4,5];return `<h2>${words[0]}</h2><p>${generic[k].paras[1]}</p><div class="table-scroll"><table class="wind-table"><thead><tr><th>${words[1]}</th><th>${words[0]}</th><th>${words[2]}</th></tr></thead><tbody>${months.map((m,i)=>`<tr><td>${m}</td><td><span class="wind-level" aria-label="${levels[i]} / 5">${[1,2,3,4,5].map(x=>`<i class="${x<=levels[i]?'on':''}"></i>`).join('')}</span></td><td>${levels[i]>=4?words[3]:levels[i]===3?words[4]:words[5]}</td></tr>`).join('')}</tbody></table></div><div class="callout">${words[6]}</div>${sourceSection(k,'wind')}`};

